* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.converter-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 1rem;
  width: 100%;
  max-width: 480px;
  padding: 2rem;
}

.converter-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

.app-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.app-subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.form-group label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text-muted);
}

.input-field, .select-field {
  background-color: #0b1120;
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  color: var(--text-main);
  padding: 0.75rem 1rem;
  font-size: 1rem;
  outline: none;
}

.currency-row {
  display: flex;
  align-items: flex-end;
  gap: 0.75rem;
}

.flex-1 {
  flex: 1;
}

.swap-button {
  background: #0b1120;
  border: 1px solid var(--border-color);
  color: var(--primary);
  border-radius: 0.5rem;
  width: 2.75rem;
  height: 2.75rem;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  margin-bottom: 1.25rem;
}

.result-container {
  background-color: #0b1120;
  border: 1px solid #334155;
  border-radius: 0.75rem;
  padding: 1.25rem;
  text-align: center;
  margin: 1.5rem 0;
}

.rate-info {
  font-size: 0.875rem;
  color: #94a3b8;
}

.converted-amount {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f8fafc;
}

.converter-footer {
  border-top: 1px solid #334155;
  padding-top: 1.25rem;
}

.history-list {
  list-style: none;
  font-size: 0.8125rem;
  color: #94a3b8;
}

const rates = { USD: 1.0, EUR: 0.92, GBP: 0.79 };
const amountInput = document.getElementById('amount-input');
const fromCurrency = document.getElementById('from-currency');
const toCurrency = document.getElementById('to-currency');
const swapBtn = document.getElementById('swap-btn');
const rateDisplay = document.getElementById('rate-display');
const resultDisplay = document.getElementById('result-display');
const historyList = document.getElementById('history-list');

function calculateConversion() {
  const amount = parseFloat(amountInput.value) || 0;
  const from = fromCurrency.value;
  const to = toCurrency.value;
  const rate = rates[to] / rates[from];
  const result = (amount * rate).toFixed(2);
  rateDisplay.textContent = `1 ${from} = ${rate.toFixed(4)} ${to}`;
  resultDisplay.textContent = `${result} ${to}`;
}

amountInput.addEventListener('input', calculateConversion);
fromCurrency.addEventListener('change', calculateConversion);
toCurrency.addEventListener('change', calculateConversion);
swapBtn.addEventListener('click', () => {
  const temp = fromCurrency.value;
  fromCurrency.value = toCurrency.value;
  toCurrency.value = temp;
  calculateConversion();
});
calculateConversion();

